function App() {
  const [text, setText] = useState('');
  const [title, setTitle] = useState('');
  const [numSegments, setNumSegments] = useState(6);
  const [segments, setSegments] = useState([]);
  const [emotionProfiles, setEmotionProfiles] = useState([]);
  const [narrativeTension, setNarrativeTension] = useState([]);
  const [actionPace, setActionPace] = useState([]);
  const [storySpecificTerms, setStorySpecificTerms] = useState({});
  const [storySpecificInput, setStorySpecificInput] = useState('');
  const [segmentationMethod, setSegmentationMethod] = useState('auto');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [isCustomSegmentation, setIsCustomSegmentation] = useState(false);
  const [customSegments, setCustomSegments] = useState([{ name: 'exposition', content: '' }]);
  const [showHelp, setShowHelp] = useState(false);
  const [useCustomTerms, setUseCustomTerms] = useState(false);
  const [visualizationType, setVisualizationType] = useState('stacked');
  const [emotionChangeThreshold, setEmotionChangeThreshold] = useState(3.0);
  const [isModelLoading, setIsModelLoading] = useState(false);
  const [useStopWordRemoval, setUseStopWordRemoval] = useState(true);
  const [modelLoaded, setModelLoaded] = useState(false);
  const [modelName, setModelName] = useState('j-hartmann/emotion-english-distilroberta-base'); // Actual EmoRoBERTa model
  const [multiFactorSegmentation, setMultiFactorSegmentation] = useState(true);
  const [factorWeights, setFactorWeights] = useState({
    emotion: 1.0,
    tension: 0.8,
    pace: 0.6,
    linguistic: 0.7, 
    character_danger: 0.9 
  });
  const [showModelSettings, setShowModelSettings] = useState(false);
  const [emotionClassifier, setEmotionClassifier] = useState(null); // The actual EmoRoBERTa pipeline
  const [tensionDetector, setTensionDetector] = useState(null);     // Will be created using text classification
  const [modelEnabled, setModelEnabled] = useState(true);
  const [useContentBasedStages, setUseContentBasedStages] = useState(false);
  const [linguisticAnalysisEnabled, setLinguisticAnalysisEnabled] = useState(true);
  const [characterDangerAnalysisEnabled, setCharacterDangerAnalysisEnabled] = useState(true);
  const [linguisticFeatures, setLinguisticFeatures] = useState([]);
  const [characterDangerProximity, setCharacterDangerProximity] = useState([]);
  const [showAdvancedFeatures, setShowAdvancedFeatures] = useState(false);
  const [maxTextLength, setMaxTextLength] = useState(500); // Max text length for model analysis

  // Initialize the EmoRoBERTa model
  const initializeModel = async () => {
    if (!modelEnabled) return;
    
    try {
      setIsModelLoading(true);
      setErrorMessage('');
      
      // Load the emotion classification model using transformers.js pipeline
      const classifier = await pipeline(
        'text-classification', 
        modelName,
        { quantized: true } // Use quantized model for better performance in browser
      );
      
      setEmotionClassifier(classifier);
      console.log("EmoRoBERTa model initialized successfully");
      
      // We'll create a zero-shot classifier for custom emotions like tension, danger, relief
      const zeroShotClassifier = await pipeline(
        'zero-shot-classification',
        'Xenova/distilbert-base-uncased-mnli', // Using a lightweight zero-shot model
        { quantized: true }
      );
      
      setTensionDetector(zeroShotClassifier);
      console.log("Zero-shot classifier initialized for custom emotions");
      
      setModelLoaded(true);
      setIsModelLoading(false);
    } catch (error) {
      console.error("Error loading emotion model:", error);
      setErrorMessage("Failed to load emotion analysis model: " + error.message);
      setIsModelLoading(false);
    }
  };

  // Run emotion analysis using the actual EmoRoBERTa model
  const runEmotionAnalysis = async (text) => {
    if (!modelEnabled || !text.trim()) {
      // Fallback to rule-based analysis if model isn't enabled
      return generateRuleBasedEmotions(text);
    }

    if (!emotionClassifier || !tensionDetector) {
      console.warn("Models not loaded, falling back to rule-based analysis");
      return generateRuleBasedEmotions(text);
    }

    try {
      // Prepare text - limit length for model input
      const processedText = text.slice(0, maxTextLength);
      
      // Run EmoRoBERTa emotion classification
      const emotionResults = await emotionClassifier(processedText);
      
      // Process EmoRoBERTa results
      const emotions = {};
      emotionResults.forEach(result => {
        const emotion = result.label.toLowerCase();
        const score = result.score * 10; // Scale to 0-10
        
        // Map to our emotion categories
        const mappedEmotion = EMO_ROBERTA_MAPPING[emotion];
        if (mappedEmotion) {
          emotions[mappedEmotion] = score;
        }
      });
      
      // For custom emotions not in EmoRoBERTa's output, use zero-shot classification
      const customEmotions = ["tension", "danger", "relief"];
      
      // Run zero-shot classification for custom emotions
      const tensionResult = await tensionDetector(
        processedText,
        TENSION_TERMS, // Use our predefined terms as candidate labels
        { multi_label: true }
      );
      
      // Process zero-shot results for custom emotions
      // Calculate average confidence across related terms
      let tensionScore = 0;
      let dangerScore = 0;
      let reliefScore = 0;
      
      tensionResult.scores.forEach((score, idx) => {
        const term = tensionResult.labels[idx];
        if (EMOTION_INDICATORS.tension.includes(term)) {
          tensionScore += score;
        } else if (EMOTION_INDICATORS.danger.includes(term)) {
          dangerScore += score;
        } else if (EMOTION_INDICATORS.relief.includes(term)) {
          reliefScore += score;
        }
      });
      
      // Normalize scores
      emotions.tension = tensionScore * 10; // Scale to 0-10
      emotions.danger = dangerScore * 10;
      emotions.relief = reliefScore * 10;
      
      // Add calculated narrative tension based on text structure
      const narrativeTensionScore = calculateNarrativeTensionScore(text);
      emotions.tension = Math.max(emotions.tension || 0, narrativeTensionScore);
      
      // Ensure all emotions are populated
      Object.keys(EMOTION_WEIGHTS).forEach(emotion => {
        if (emotions[emotion] === undefined) {
          emotions[emotion] = 0;
        }
      });
      
      return emotions;
    } catch (error) {
      console.error("Error running EmoRoBERTa analysis:", error);
      // Fallback to rule-based approach if the model fails
      return generateRuleBasedEmotions(text);
    }
  };

  // Generate rule-based emotion scores (fallback)
  const generateRuleBasedEmotions = (text) => {
    const emotions = {};
    const emotionKeys = Object.keys(EMOTION_WEIGHTS);
    const lowerText = text.toLowerCase();

    // Count keyword occurrences using our emotion indicators
    emotionKeys.forEach(emotion => {
      if (EMOTION_INDICATORS[emotion]) {
        let count = 0;
        EMOTION_INDICATORS[emotion].forEach(keyword => {
          const regex = new RegExp(`\\b${keyword}\\b`, 'gi');
          const matches = lowerText.match(regex);
          if (matches) count += matches.length;
        });
        // Convert count to score (0-10)
        emotions[emotion] = Math.min(10, count * 2);
      } else {
        emotions[emotion] = 0;
      }
    });

    // Ensure at least some emotion is present
    if (Object.values(emotions).reduce((sum, val) => sum + val, 0) < 3) {
      // If very little emotion detected, add some based on text statistics
      emotions.tension = Math.min(10, (lowerText.split(/[!?]/).length - 1) * 1.5);
      emotions.surprise = Math.min(10, lowerText.length / 500);
    }

    // Add calculated tension score
    emotions.tension = Math.max(emotions.tension || 0, calculateNarrativeTensionScore(text));

    return emotions;
  };

  // Calculate narrative tension based on narrative elements
  const calculateNarrativeTensionScore = (text) => {
    const lowerText = text.toLowerCase();
    let tensionScore = 0;

    // Keywords indicating tension
    const tensionIndicators = [
      { words: ["conflict", "fight", "battle", "struggle", "confrontation"], weight: 1.5 },
      { words: ["problem", "challenge", "obstacle", "difficulty"], weight: 1.0 },
      { words: ["danger", "threat", "risk", "peril"], weight: 2.0 },
      { words: ["time", "deadline", "hurry", "quick"], weight: 0.8 },
      { words: ["but", "however", "although", "despite", "though"], weight: 0.3 },
    ];

    // Check for presence of tension indicators
    tensionIndicators.forEach(indicator => {
      indicator.words.forEach(word => {
        const regex = new RegExp(`\\b${word}\\b`, 'gi');
        const matches = lowerText.match(regex);
        if (matches) {
          tensionScore += matches.length * indicator.weight;
        }
      });
    });

    // Check for markers of high tension in writing style
    const exclamationCount = (lowerText.match(/!/g) || []).length;
    const questionCount = (lowerText.match(/\?/g) || []).length;
    const ellipsisCount = (lowerText.match(/\.\.\./g) || []).length;
    tensionScore += exclamationCount * 0.5;
    tensionScore += questionCount * 0.3;
    tensionScore += ellipsisCount * 0.2;

    // Normalize to 0-10 scale
    return Math.min(10, tensionScore);
  };

  // Analyze linguistic features of text
  const analyzeLinguisticFeatures = (text) => {
    if (!linguisticAnalysisEnabled || !text.trim()) {
      return {
        sentenceLength: 0,
        clauseComplexity: 0,
        questions: 0,
        imperatives: 0,
        emphasis: 0,
        intensifiers: 0,
        repetition: 0,
        rhetorical: 0
      };
    }

    try {
      const sentences = sentenceTokenize(text);
      const lowerText = text.toLowerCase();
      const words = text.split(/\s+/).filter(w => w.trim().length > 0);
      
      // 1. Sentence structure analysis
      const avgSentenceLength = sentences.length > 0 ? 
        words.length / sentences.length : 0;
      
      // Estimate clause complexity by counting commas and conjunctions
      const commaCount = (text.match(/,/g) || []).length;
      const conjunctions = ['and', 'but', 'or', 'nor', 'for', 'yet', 'so', 'because', 'although', 'since', 'unless', 'while'];
      let conjunctionCount = 0;
      conjunctions.forEach(conj => {
        const regex = new RegExp(`\\b${conj}\\b`, 'gi');
        const matches = text.match(regex);
        if (matches) conjunctionCount += matches.length;
      });
      
      const clauseComplexity = sentences.length > 0 ? 
        (commaCount + conjunctionCount) / sentences.length : 0;
      
      // Question and imperative detection
      const questionCount = sentences.filter(s => s.trim().endsWith('?')).length;
      
      // Simple imperative detection - sentences starting with verbs
      const doc = nlp(text);
      const potentialImperatives = sentences.filter(s => {
        const firstWord = s.trim().split(/\s+/)[0].toLowerCase();
        const firstWordDoc = nlp(firstWord);
        return firstWordDoc.verbs().length > 0;
      });
      const imperativeCount = potentialImperatives.length;
      
      // 2. Stylistic element identification
      const emphasisMarkers = (text.match(/[*_]{1,2}[^*_]+[*_]{1,2}/g) || []).length; // Markdown style emphasis
      const heavyPunctuation = (text.match(/[!?]{2,}/g) || []).length;
      
      // Count intensifiers
      let intensifierCount = 0;
      INTENSIFIERS.forEach(intensifier => {
        const regex = new RegExp(`\\b${intensifier}\\b`, 'gi');
        const matches = text.match(regex);
        if (matches) intensifierCount += matches.length;
      });
      
      // Detect repetition patterns
      // Simple repetition detection - repeated words or phrases
      const words3 = text.toLowerCase().split(/\s+/).map(w => w.replace(/[^\w]/g, ''));
      let repetitionCount = 0;
      for (let i = 0; i < words3.length - 1; i++) {
        if (words3[i] && words3[i] === words3[i+1]) {
          repetitionCount++;
        }
      }
      
      // 3. Rhetorical device recognition
      let rhetoricalCount = 0;
      
      // Check for hyperbole
      RHETORICAL_PATTERNS.hyperbole.forEach(term => {
        const regex = new RegExp(`\\b${term}\\b`, 'gi');
        const matches = text.match(regex);
        if (matches) rhetoricalCount += matches.length * 0.5;
      });
      
      // Check for similes and metaphors
      RHETORICAL_PATTERNS.simile.forEach(pattern => {
        rhetoricalCount += (text.toLowerCase().split(pattern).length - 1) * 0.8;
      });
      
      RHETORICAL_PATTERNS.metaphor.forEach(pattern => {
        rhetoricalCount += (text.toLowerCase().split(pattern).length - 1) * 0.8;
      });
      
      // Normalize all values to 0-10 scale
      const normalizedFeatures = {
        sentenceLength: Math.min(10, avgSentenceLength / 3),
        clauseComplexity: Math.min(10, clauseComplexity * 3),
        questions: Math.min(10, (questionCount / sentences.length) * 20),
        imperatives: Math.min(10, (imperativeCount / sentences.length) * 20),
        emphasis: Math.min(10, (emphasisMarkers + heavyPunctuation) / (sentences.length / 2)),
        intensifiers: Math.min(10, intensifierCount / (words.length / 50) * 2),
        repetition: Math.min(10, repetitionCount * 2),
        rhetorical: Math.min(10, rhetoricalCount)
      };
      
      return normalizedFeatures;
    } catch (error) {
      console.error("Error analyzing linguistic features:", error);
      return {
        sentenceLength: 0,
        clauseComplexity: 0,
        questions: 0,
        imperatives: 0,
        emphasis: 0,
        intensifiers: 0,
        repetition: 0,
        rhetorical: 0
      };
    }
  };

  // Calculate character-danger proximity
  const calculateCharacterDangerProximity = (text) => {
    if (!characterDangerAnalysisEnabled || !text.trim()) {
      return 0;
    }

    try {
      const sentences = sentenceTokenize(text);
      const lowerText = text.toLowerCase();
      let proximityScore = 0;
      
      // Specific character names from the text or custom inputs
      const customCharacterNames = storySpecificInput
        .split(',')
        .map(term => term.trim().toLowerCase())
        .filter(term => term.length > 0);
      
      const allCharacterTerms = [...CHARACTER_INDICATORS, ...customCharacterNames];
      
      // Find sentences containing both character references and danger terms
      sentences.forEach(sentence => {
        const lowerSentence = sentence.toLowerCase();
        
        // Check if sentence contains both character and danger terms
        const hasCharacter = allCharacterTerms.some(term => 
          new RegExp(`\\b${term}\\b`, 'i').test(lowerSentence));
          
        const hasDanger = DANGER_INDICATORS.some(term => 
          new RegExp(`\\b${term}\\b`, 'i').test(lowerSentence));
          
        if (hasCharacter && hasDanger) {
          // Basic proximity - they appear in the same sentence
          proximityScore += 1;
          
          // Advanced: check character as subject of danger
          // This is a simplified approach - ideally would use proper NLP parsing
          const doc = nlp(sentence);
          const subjects = doc.match('#Noun').before('#Verb').out('array');
          const objects = doc.match('#Noun').after('#Verb').out('array');
          
          // Check if any character term is in subject position
          const characterIsSubject = subjects.some(subject => 
            allCharacterTerms.some(term => 
              subject.toLowerCase().includes(term)));
              
          // If character is subject of danger action, higher score
          if (characterIsSubject) proximityScore += 0.5;
          
          // Check for direct danger to character (character as object)
          const characterIsObject = objects.some(object => 
            allCharacterTerms.some(term => 
              object.toLowerCase().includes(term)));
              
          // If character is object of danger action, highest score
          if (characterIsObject) proximityScore += 1;
        }
      });
      
      // Normalize to 0-10 scale based on text length
      return Math.min(10, (proximityScore / sentences.length) * 25);
    } catch (error) {
      console.error("Error calculating character-danger proximity:", error);
      return 0;
    }
  };

  // Function to split text into sentences
  const sentenceTokenize = (text) => {
    // Handle common abbreviations and edge cases
    const preparedText = text
      .replace(/([.?!])\s*(?=[A-Z])/g, "$1|")
      .replace(/(\b[A-Z][a-z]{1,2})\./g, "$1|") // Handle abbreviations like Mr. Dr. etc.
      .replace(/\.\.\./g, "…"); // Handle ellipsis
    return preparedText.split(/[|]/).filter(sentence => sentence.trim().length > 0);
  };

  // Enhanced action pace calculation with linguistic features
  const calculateActionPace = (text) => {
    try {
      const doc = nlp(text);
      
      // Get all verbs
      const verbs = doc.verbs().out('array');
      
      // Get total words excluding punctuation and whitespace
      const totalWords = text.split(/\s+/).filter(w => w.trim().length > 0).length;
      if (totalWords === 0) return 0;
      
      // Focus on action verbs by checking verb properties in Compromise
      const actionVerbs = doc.verbs().if('#PresentTense').out('array');
      
      // Enhanced: Specifically look for verbs in our action verb list
      let highImpactActionCount = 0;
      ACTION_VERBS.forEach(actionVerb => {
        const regex = new RegExp(`\\b${actionVerb}\\b`, 'gi');
        const matches = text.match(regex);
        if (matches) highImpactActionCount += matches.length;
      });
      
      // Calculate verb density with NLP tagging (more accurate than simple word lists)
      const verbDensity = (verbs.length / totalWords) * 100;
      const actionVerbDensity = (actionVerbs.length / totalWords) * 100;
      
      // Calculate high-impact action verb density
      //const highImpactDensity = (highImpactActionCount / totalWords) * 100;
      
      // Sentence structure
      // Calculate high-impact action verb density
      const highImpactDensity = (highImpactActionCount / totalWords) * 100;
      
      // Sentence structure analysis for pace
      const sentences = sentenceTokenize(text);
      const avgSentenceLength = sentences.length > 0 ? totalWords / sentences.length : 0;
      
      // Short sentences often indicate faster pace
      const shortSentenceBonus = avgSentenceLength < 10 ? (10 - avgSentenceLength) * 0.2 : 0;
      
      // Count punctuation that indicates action or urgency
      const exclamationCount = (text.match(/!/g) || []).length;
      const dashCount = (text.match(/—|-/g) || []).length;
      const ellipsisCount = (text.match(/\.\.\./g) || []).length;
      const urgentPunctuationDensity = ((exclamationCount + dashCount + ellipsisCount) / totalWords) * 100;
      
      // Calculate final pace score (0-10 scale)
      let paceScore = 
        (verbDensity * 0.2) +               // Basic verb density
        (actionVerbDensity * 0.3) +         // Action verb density (higher weight)
        (highImpactDensity * 0.5) +         // High-impact verbs (highest weight)
        shortSentenceBonus +                // Bonus for short sentences
        (urgentPunctuationDensity * 0.3);   // Punctuation that creates urgency
      
      // Normalize to 0-10 scale
      return Math.min(10, paceScore / 2);
    } catch (error) {
      console.error("Error calculating action pace:", error);
      return 0;
    }
  };

  // Function to segment text by major story beats (auto segmentation)
  const autoSegmentText = (text) => {
    try {
      if (text.trim().length === 0) return [];
      
      const segments = [];
      
      if (multiFactorSegmentation) {
        // Multi-factor approach using emotion shifts, tension, pacing, and linguistic features
        
        // First split by paragraphs
        const paragraphs = text.split(/\n\s*\n/);
        if (paragraphs.length <= numSegments) {
          // If we have fewer paragraphs than desired segments, just use paragraphs
          return paragraphs.map((p, i) => ({ 
            text: p, 
            name: `Segment ${i+1}` 
          }));
        }
        
        // Group paragraphs into initial segments based on desired number
        const paragraphsPerSegment = Math.max(1, Math.floor(paragraphs.length / numSegments));
        let initialSegments = [];
        
        for (let i = 0; i < paragraphs.length; i += paragraphsPerSegment) {
          const segmentText = paragraphs.slice(i, i + paragraphsPerSegment).join("\n\n");
          initialSegments.push(segmentText);
        }
        
        // Ensure we don't exceed desired segment count by combining the last segments if needed
        while (initialSegments.length > numSegments) {
          const lastSegment = initialSegments.pop();
          const secondLastSegment = initialSegments.pop();
          initialSegments.push(`${secondLastSegment}\n\n${lastSegment}`);
        }
        
        // Now analyze each segment for emotion, tension, pace, etc.
        const analyzedSegments = initialSegments.map((segmentText, index) => {
          // Run analyses on each segment
          const emotions = generateRuleBasedEmotions(segmentText); // Using rule-based for speed
          const linguisticFeatures = analyzeLinguisticFeatures(segmentText);
          const characterDanger = calculateCharacterDangerProximity(segmentText);
          const paceScore = calculateActionPace(segmentText);
          
          // Calculate tension score
          let tensionScore = 0;
          Object.keys(emotions).forEach(emotion => {
            tensionScore += emotions[emotion] * (EMOTION_WEIGHTS[emotion] || 0);
          });
          
          // Add linguistic and character danger factors
          tensionScore += 
            (linguisticFeatures.emphasis * 0.3) + 
            (linguisticFeatures.intensifiers * 0.2) +
            (characterDanger * 0.5);
          
          return {
            text: segmentText,
            name: `Segment ${index + 1}`,
            emotionProfile: emotions,
            tensionScore: tensionScore,
            paceScore: paceScore,
            linguisticFeatures: linguisticFeatures,
            characterDanger: characterDanger
          };
        });
        
        // Return the analyzed segments
        return analyzedSegments.map(segment => ({
          text: segment.text,
          name: segment.name
        }));
      } else {
        // Simple approach - evenly divide text
        const wordCount = text.split(/\s+/).length;
        const wordsPerSegment = Math.floor(wordCount / numSegments);
        
        const words = text.split(/\s+/);
        for (let i = 0; i < numSegments; i++) {
          const start = i * wordsPerSegment;
          const end = (i === numSegments - 1) ? words.length : (i + 1) * wordsPerSegment;
          const segmentText = words.slice(start, end).join(' ');
          segments.push({
            text: segmentText,
            name: `Segment ${i + 1}`
          });
        }
      }
      
      return segments;
    } catch (error) {
      console.error("Error in auto segmentation:", error);
      // Fallback to simple equal segments
      return splitTextIntoEqualSegments(text, numSegments);
    }
  };

  // Split text into equal segments (fallback method)
  const splitTextIntoEqualSegments = (text, count) => {
    if (!text || text.length === 0) return [];
    const segments = [];
    const approxLengthPerSegment = Math.ceil(text.length / count);
    
    for (let i = 0; i < count; i++) {
      const startPos = i * approxLengthPerSegment;
      let endPos = (i + 1) * approxLengthPerSegment;
      
      // Adjust to not break in the middle of words
      if (endPos < text.length) {
        while (endPos < text.length && text[endPos] !== ' ' && text[endPos] !== '\n') {
          endPos++;
        }
      } else {
        endPos = text.length;
      }
      
      const segmentText = text.substring(startPos, endPos);
      segments.push({
        text: segmentText,
        name: `Segment ${i + 1}`
      });
    }
    
    return segments;
  };

  // Apply narrative arc structure to segments
  const mapSegmentsToNarrativeArc = (segments) => {
    const arcKeys = Object.keys(DEFAULT_ARC_STRUCTURE);
    
    // If number of segments matches arc keys, use direct mapping
    if (segments.length === arcKeys.length) {
      return segments.map((segment, i) => ({
        ...segment,
        name: arcKeys[i].replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase())
      }));
    } 
    
    // If fewer segments than arc structure, merge some arc elements
    if (segments.length < arcKeys.length) {
      const combinedArc = [];
      const keysPerSegment = Math.ceil(arcKeys.length / segments.length);
      
      for (let i = 0; i < segments.length; i++) {
        const startKey = i * keysPerSegment;
        const endKey = Math.min((i + 1) * keysPerSegment, arcKeys.length);
        const arcKeysForSegment = arcKeys.slice(startKey, endKey);
        
        // Create name by joining arc components
        const name = arcKeysForSegment
          .map(k => k.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()))
          .join(' / ');
          
        combinedArc.push({
          ...segments[i],
          name
        });
      }
      
      return combinedArc;
    }
    
    // If more segments than arc structure, reuse arc elements with numbers
    const expandedArc = [];
    let currentArcIndex = 0;
    
    for (let i = 0; i < segments.length; i++) {
      const arcIndex = Math.min(
        Math.floor((i / segments.length) * arcKeys.length),
        arcKeys.length - 1
      );
      
      // If we moved to a new arc element, reset counter
      if (arcIndex !== currentArcIndex) {
        currentArcIndex = arcIndex;
      }
      
      const arcName = arcKeys[arcIndex]
        .replace(/_/g, ' ')
        .replace(/\b\w/g, l => l.toUpperCase());
      
      expandedArc.push({
        ...segments[i],
        name: arcName
      });
    }
    
    return expandedArc;
  };

  // Calculate total word count
  const calculateWordCount = (text) => {
    if (!text) return 0;
    return text.split(/\s+/).filter(word => word.trim() !== '').length;
  };

  // Process text for analysis
  const processText = async () => {
    if (!text.trim()) {
      setErrorMessage("Please enter some text to analyze.");
      return;
    }
    
    try {
      setIsAnalyzing(true);
      setErrorMessage('');
      
      // Determine segmentation method
      let processedSegments = [];
      
      if (isCustomSegmentation) {
        // Use custom segment data
        processedSegments = customSegments.map(segment => ({
          text: segment.content,
          name: segment.name
        }));
      } else if (segmentationMethod === 'auto') {
        // Use auto segmentation
        processedSegments = autoSegmentText(text);
      } else if (segmentationMethod === 'arc') {
        // Use narrative arc-based segmentation
        const autoSegments = autoSegmentText(text);
        processedSegments = mapSegmentsToNarrativeArc(autoSegments);
      }
      
      // Check if we have valid segments
      if (processedSegments.length === 0) {
        setErrorMessage("Could not segment text properly. Please try a different segmentation method.");
        setIsAnalyzing(false);
        return;
      }
      
      setSegments(processedSegments);
      
      // Analyze linguistics and character-danger proximity for each segment
      const linguisticFeatureResults = [];
      const characterDangerResults = [];
      
      for (const segment of processedSegments) {
        if (linguisticAnalysisEnabled) {
          const features = analyzeLinguisticFeatures(segment.text);
          linguisticFeatureResults.push(features);
        }
        
        if (characterDangerAnalysisEnabled) {
          const proximity = calculateCharacterDangerProximity(segment.text);
          characterDangerResults.push(proximity);
        }
      }
      
      setLinguisticFeatures(linguisticFeatureResults);
      setCharacterDangerProximity(characterDangerResults);
      
      // Analyze emotion profiles for each segment
      const emotionResults = [];
      for (const segment of processedSegments) {
        const emotions = await runEmotionAnalysis(segment.text);
        emotionResults.push(emotions);
      }
      
      setEmotionProfiles(emotionResults);
      
      // Calculate action pace for each segment
      const paceResults = [];
      for (const segment of processedSegments) {
        const pace = calculateActionPace(segment.text);
        paceResults.push(pace);
      }
      
      setActionPace(paceResults);
      
      // Calculate narrative tension for each segment using emotion weights
      const tensionResults = [];
      for (let i = 0; i < processedSegments.length; i++) {
        let tensionScore = 0;
        
        // Calculate tension based on emotions
        if (emotionResults[i]) {
          Object.keys(emotionResults[i]).forEach(emotion => {
            tensionScore += emotionResults[i][emotion] * (EMOTION_WEIGHTS[emotion] || 0);
          });
        }
        
        // Factor in narrative arc position if using arc-based segmentation
        if (segmentationMethod === 'arc') {
          const arcName = processedSegments[i].name.toLowerCase();
          let arcWeight = 1.0;
          
          // Find matching arc structure
          Object.keys(DEFAULT_ARC_STRUCTURE).forEach(key => {
            if (arcName.includes(key.replace(/_/g, ' '))) {
              arcWeight = DEFAULT_ARC_STRUCTURE[key].tension_weight;
            }
          });
          
          tensionScore *= arcWeight;
        }
        
        // Add linguistic features contribution to tension
        if (linguisticAnalysisEnabled && linguisticFeatureResults[i]) {
          tensionScore += 
            (linguisticFeatureResults[i].emphasis * factorWeights.linguistic * 0.5) +
            (linguisticFeatureResults[i].questions * factorWeights.linguistic * 0.3);
        }
        
        // Add character-danger proximity contribution
        if (characterDangerAnalysisEnabled) {
          tensionScore += characterDangerResults[i] * factorWeights.character_danger;
        }
        
        // Add pace contribution to tension
        tensionScore += paceResults[i] * factorWeights.pace * 0.5;
        
        // Ensure tension is within 0-10 range
        tensionScore = Math.min(10, Math.max(0, tensionScore));
        tensionResults.push(tensionScore);
      }
      
      setNarrativeTension(tensionResults);
      
      // If story-specific terms are enabled, extract and count custom terms
      if (useCustomTerms && storySpecificInput.trim()) {
        const terms = storySpecificInput.split(',').map(term => term.trim());
        const termCounts = {};
        
        terms.forEach(term => {
          if (term) {
            termCounts[term] = [];
            
            processedSegments.forEach(segment => {
              const regex = new RegExp(`\\b${term}\\b`, 'gi');
              const count = (segment.text.match(regex) || []).length;
              termCounts[term].push(count);
            });
          }
        });
        
        setStorySpecificTerms(termCounts);
      }
      
      setIsAnalyzing(false);
    } catch (error) {
      console.error("Error processing text:", error);
      setErrorMessage(`Error analyzing text: ${error.message}`);
      setIsAnalyzing(false);
    }
  };

  // Load or initialize the model when the component mounts
  useEffect(() => {
    if (modelEnabled && !modelLoaded && !isModelLoading) {
      initializeModel();
    }
  }, [modelEnabled]);

  // Set up the custom segments when changing between custom and auto segmentation
  useEffect(() => {
    if (isCustomSegmentation && customSegments.length === 1 && customSegments[0].content === '') {
      // Initialize with standard narrative arc segments
      const arcSegments = Object.keys(DEFAULT_ARC_STRUCTURE).map(arcKey => ({
        name: arcKey.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
        content: ''
      }));
      setCustomSegments(arcSegments);
    }
  }, [isCustomSegmentation]);

  // Handle custom segment changes
  const handleCustomSegmentChange = (index, field, value) => {
    const updatedSegments = [...customSegments];
    updatedSegments[index][field] = value;
    setCustomSegments(updatedSegments);
  };

  // Add a new custom segment
  const addCustomSegment = () => {
    setCustomSegments([...customSegments, { name: `Segment ${customSegments.length + 1}`, content: '' }]);
  };

  // Remove a custom segment
  const removeCustomSegment = (index) => {
    if (customSegments.length > 1) {
      const updatedSegments = customSegments.filter((_, i) => i !== index);
      setCustomSegments(updatedSegments);
    }
  };

  // Detect empty segments
  const hasEmptySegments = () => {
    return customSegments.some(segment => !segment.content.trim());
  };

  // Get color for emotion
  const getEmotionColor = (emotion) => {
    return EMOTION_COLORS[emotion] || '#999999';
  };

  // Format emotional changes data for the chart
  const formatEmotionalChangesData = () => {
    if (!emotionProfiles.length) return [];

    const data = [];
    const emotionKeys = Object.keys(EMOTION_WEIGHTS);

    for (let i = 0; i < segments.length; i++) {
      const segmentData = {
        name: segments[i].name
      };

      emotionKeys.forEach(emotion => {
        if (emotionProfiles[i] && emotionProfiles[i][emotion] !== undefined) {
          segmentData[emotion] = emotionProfiles[i][emotion];
        } else {
          segmentData[emotion] = 0;
        }
      });

      data.push(segmentData);
    }

    return data;
  };

  // Format narrative tension data for the chart
  const formatNarrativeTensionData = () => {
    if (!narrativeTension.length) return [];

    return segments.map((segment, index) => ({
      name: segment.name,
      value: narrativeTension[index] || 0
    }));
  };

  // Format action pace data for the chart
  const formatActionPaceData = () => {
    if (!actionPace.length) return [];

    return segments.map((segment, index) => ({
      name: segment.name,
      value: actionPace[index] || 0
    }));
  };

  // Format story-specific terms data for the chart
  const formatStorySpecificTermsData = () => {
    if (Object.keys(storySpecificTerms).length === 0) return [];

    return segments.map((segment, index) => {
      const termData = { name: segment.name };
      
      Object.keys(storySpecificTerms).forEach(term => {
        termData[term] = storySpecificTerms[term][index] || 0;
      });
      
      return termData;
    });
  };

  // Format linguistic features data for the chart
  const formatLinguisticFeaturesData = () => {
    if (!linguisticFeatures.length) return [];
    
    return segments.map((segment, index) => {
      const features = linguisticFeatures[index] || {};
      return {
        name: segment.name,
        sentenceLength: features.sentenceLength || 0,
        clauseComplexity: features.clauseComplexity || 0,
        questions: features.questions || 0,
        imperatives: features.imperatives || 0,
        emphasis: features.emphasis || 0,
        intensifiers: features.intensifiers || 0,
        repetition: features.repetition || 0,
        rhetorical: features.rhetorical || 0
      };
    });
  };

  // Format character-danger proximity data
  const formatCharacterDangerData = () => {
    if (!characterDangerProximity.length) return [];
    
    return segments.map((segment, index) => ({
      name: segment.name,
      value: characterDangerProximity[index] || 0
    }));
  };

  // Handle file upload for text input
  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (!file) return;
    
    const reader = new FileReader();
    reader.onload = (e) => {
      setText(e.target.result);
    };
    reader.readAsText(file);
  };

  // Export analysis data as CSV
  const exportAnalysisCSV = () => {
    if (!segments.length || !emotionProfiles.length) {
      setErrorMessage("No analysis data to export.");
      return;
    }
    
    try {
      // Create headers
      const emotions = Object.keys(EMOTION_WEIGHTS);
      const headers = ["Segment", "Word Count", ...emotions, "Tension", "Pace"];
      
      // Add linguistic features if enabled
      if (linguisticAnalysisEnabled) {
        headers.push("Sentence Length", "Clause Complexity", "Questions", "Imperatives", 
                    "Emphasis", "Intensifiers", "Repetition", "Rhetorical Devices");
      }
      
      // Add character-danger proximity if enabled
      if (characterDangerAnalysisEnabled) {
        headers.push("Character-Danger Proximity");
      }
      
      // Add custom terms if used
      if (useCustomTerms) {
        Object.keys(storySpecificTerms).forEach(term => {
          headers.push(`Term: ${term}`);
        });
      }
      
      // Create rows
      const rows = segments.map((segment, i) => {
        const row = [
          segment.name,
          calculateWordCount(segment.text)
        ];
        
        // Add emotion values
        emotions.forEach(emotion => {
          row.push(emotionProfiles[i]?.[emotion] || 0);
        });
        
        // Add tension and pace
        row.push(narrativeTension[i] || 0);
        row.push(actionPace[i] || 0);
        
        // Add linguistic features if enabled
        if (linguisticAnalysisEnabled && linguisticFeatures[i]) {
          row.push(
            linguisticFeatures[i].sentenceLength || 0,
            linguisticFeatures[i].clauseComplexity || 0,
            linguisticFeatures[i].questions || 0,
            linguisticFeatures[i].imperatives || 0,
            linguisticFeatures[i].emphasis || 0,
            linguisticFeatures[i].intensifiers || 0,
            linguisticFeatures[i].repetition || 0,
            linguisticFeatures[i].rhetorical || 0
          );
        }
        
        // Add character-danger proximity if enabled
        if (characterDangerAnalysisEnabled) {
          row.push(characterDangerProximity[i] || 0);
        }
        
        // Add custom terms if used
        if (useCustomTerms) {
          Object.keys(storySpecificTerms).forEach(term => {
            row.push(storySpecificTerms[term][i] || 0);
          });
        }
        
        return row;
      });
      
      // Combine headers and rows
      const csvContent = [
        headers.join(','),
        ...rows.map(row => row.join(','))
      ].join('\n');
      
      // Create and download CSV file
      const blob = new Blob([csvContent], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `${title || 'narrative'}_analysis.csv`;
      link.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error("Error exporting analysis:", error);
      setErrorMessage(`Error exporting analysis: ${error.message}`);
    }
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <h1>Enhanced Narrative Emotion Analysis</h1>
        <p>Analyze emotional arcs and narrative tension in stories with AI-powered insights</p>
      </header>
  
      <div className="main-content">
        <div className="input-section">
          <div className="section-header">
            <h2>Story Input</h2>
            <button 
              className="help-button"
              onClick={() => setShowHelp(!showHelp)}
            >
              {showHelp ? 'Hide Help' : 'Show Help'}
            </button>
          </div>
  
          {showHelp && (
            <div className="help-section">
              <h3>How to Use This Tool</h3>
              <ol>
                <li>Paste your story or narrative text in the input area</li>
                <li>Enter a title (optional) for your analysis</li>
                <li>Choose segmentation method:
                  <ul>
                    <li><strong>Automatic</strong> - AI determines logical segments</li>
                    <li><strong>Narrative Arc</strong> - Maps to traditional story structure</li>
                    <li><strong>Custom</strong> - Define your own segments</li>
                  </ul>
                </li>
                <li>Set the number of segments (for auto segmentation)</li>
                <li>Add story-specific terms to track (optional)</li>
                <li>Click "Analyze Text" to generate visualizations</li>
              </ol>
              <h4>Advanced Options</h4>
              <ul>
                <li>Choose visualization type (stacked, line, area)</li>
                <li>Adjust emotion change threshold for detecting shifts</li>
                <li>Enable/disable AI model for more accurate analysis</li>
                <li>Toggle advanced linguistic analysis features</li>
              </ul>
            </div>
          )}
  
          <div className="form-group">
            <label htmlFor="story-title">Story Title (optional)</label>
            <input
              type="text"
              id="story-title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Enter story title"
              className="text-input"
            />
          </div>
  
          <div className="form-group">
            <label htmlFor="story-text">Story Text</label>
            <textarea
              id="story-text"
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Paste your narrative text here..."
              className="text-area"
              rows={12}
            />
          </div>
  
          <div className="form-actions">
            <button
              onClick={() => document.getElementById('file-upload').click()}
              className="secondary-button"
            >
              Upload Text File
            </button>
            <input
              id="file-upload"
              type="file"
              accept=".txt,.md,.doc,.docx"
              onChange={handleFileUpload}
              style={{ display: 'none' }}
            />
            <div className="word-count">
              Word Count: {calculateWordCount(text)}
            </div>
          </div>
  
          <div className="form-group segmentation-options">
            <label>Segmentation Method</label>
            <div className="radio-group">
              <label>
                <input
                  type="radio"
                  value="auto"
                  checked={!isCustomSegmentation && segmentationMethod === 'auto'}
                  onChange={() => {
                    setIsCustomSegmentation(false);
                    setSegmentationMethod('auto');
                  }}
                />
                Automatic
              </label>
              <label>
                <input
                  type="radio"
                  value="arc"
                  checked={!isCustomSegmentation && segmentationMethod === 'arc'}
                  onChange={() => {
                    setIsCustomSegmentation(false);
                    setSegmentationMethod('arc');
                  }}
                />
                Narrative Arc
              </label>
              <label>
                <input
                  type="radio"
                  value="custom"
                  checked={isCustomSegmentation}
                  onChange={() => setIsCustomSegmentation(true)}
                />
                Custom Segments
              </label>
            </div>
          </div>
  
          {!isCustomSegmentation && (
            <div className="form-group">
              <label htmlFor="num-segments">Number of Segments</label>
              <input
                type="number"
                id="num-segments"
                min="2"
                max="20"
                value={numSegments}
                onChange={(e) => setNumSegments(parseInt(e.target.value))}
                className="number-input"
              />
            </div>
          )}
  
          {isCustomSegmentation && (
            <div className="custom-segments">
              <h3>Custom Segments</h3>
              {customSegments.map((segment, index) => (
                <div key={index} className="custom-segment">
                  <div className="segment-header">
                    <input
                      type="text"
                      value={segment.name}
                      onChange={(e) => handleCustomSegmentChange(index, 'name', e.target.value)}
                      placeholder="Segment name"
                      className="segment-name"
                    />
                    <button
                      onClick={() => removeCustomSegment(index)}
                      className="remove-segment"
                      disabled={customSegments.length <= 1}
                    >
                      &times;
                    </button>
                  </div>
                  <textarea
                    value={segment.content}
                    onChange={(e) => handleCustomSegmentChange(index, 'content', e.target.value)}
                    placeholder="Segment content..."
                    className="segment-content"
                    rows={4}
                  />
                  <div className="segment-word-count">
                    Words: {calculateWordCount(segment.content)}
                  </div>
                </div>
              ))}
              <button onClick={addCustomSegment} className="add-segment">
                + Add Segment
              </button>
            </div>
          )}
  
          <div className="form-group">
            <label>
              <input
                type="checkbox"
                checked={useCustomTerms}
                onChange={(e) => setUseCustomTerms(e.target.checked)}
              />
              Track Story-Specific Terms
            </label>
            {useCustomTerms && (
              <input
                type="text"
                value={storySpecificInput}
                onChange={(e) => setStorySpecificInput(e.target.value)}
                placeholder="Enter terms separated by commas (e.g., dragon, magic, sword)"
                className="text-input"
              />
            )}
          </div>
  
          <div className="visualization-options">
            <h3>Visualization Options</h3>
            <div className="form-group">
              <label>Chart Type</label>
              <select
                value={visualizationType}
                onChange={(e) => setVisualizationType(e.target.value)}
                className="select-input"
              >
                <option value="stacked">Stacked Area</option>
                <option value="line">Line Chart</option>
                <option value="area">Area Chart</option>
                <option value="bar">Bar Chart</option>
              </select>
            </div>
  
            <button
              className="toggle-advanced"
              onClick={() => setShowAdvancedFeatures(!showAdvancedFeatures)}
            >
              {showAdvancedFeatures ? 'Hide Advanced Options' : 'Show Advanced Options'}
            </button>
  
            {showAdvancedFeatures && (
              <div className="advanced-options">
                <div className="form-group">
                  <label>
                    <input
                      type="checkbox"
                      checked={modelEnabled}
                      onChange={(e) => setModelEnabled(e.target.checked)}
                    />
                    Use AI Emotion Model (More Accurate)
                  </label>
                </div>
  
                <div className="form-group">
                  <label>
                    <input
                      type="checkbox"
                      checked={linguisticAnalysisEnabled}
                      onChange={(e) => setLinguisticAnalysisEnabled(e.target.checked)}
                    />
                    Enable Linguistic Analysis
                  </label>
                </div>
  
                <div className="form-group">
                  <label>
                    <input
                      type="checkbox"
                      checked={characterDangerAnalysisEnabled}
                      onChange={(e) => setCharacterDangerAnalysisEnabled(e.target.checked)}
                    />
                    Enable Character-Danger Analysis
                  </label>
                </div>
  
                <div className="form-group">
                  <label>
                    <input
                      type="checkbox"
                      checked={useStopWordRemoval}
                      onChange={(e) => setUseStopWordRemoval(e.target.checked)}
                    />
                    Remove Common Stop Words
                  </label>
                </div>
              </div>
            )}
  
            <button
              className="toggle-model-settings"
              onClick={() => setShowModelSettings(!showModelSettings)}
            >
              {showModelSettings ? 'Hide Model Settings' : 'Model Settings'}
            </button>
  
            {showModelSettings && (
              <div className="model-settings">
                <div className="form-group">
                  <label htmlFor="model-name">Model Name</label>
                  <input
                    type="text"
                    id="model-name"
                    value={modelName}
                    onChange={(e) => setModelName(e.target.value)}
                    className="text-input"
                  />
                </div>
  
                <div className="form-group">
                  <label htmlFor="max-text-length">Max Analysis Length</label>
                  <input
                    type="number"
                    id="max-text-length"
                    value={maxTextLength}
                    onChange={(e) => setMaxTextLength(parseInt(e.target.value))}
                    className="number-input"
                    min="100"
                    max="2000"
                  />
                </div>
              </div>
            )}
  
            <div className="factor-weights">
              <h4>Analysis Factor Weights</h4>
              {Object.entries(factorWeights).map(([factor, weight]) => (
                <div className="form-group" key={factor}>
                  <label>{factor.replace(/_/g, ' ').toUpperCase()}</label>
                  <input
                    type="range"
                    min="0"
                    max="2"
                    step="0.1"
                    value={weight}
                    onChange={(e) => setFactorWeights(prev => ({
                      ...prev,
                      [factor]: parseFloat(e.target.value)
                    }))}
                  />
                  <span>{weight.toFixed(1)}</span>
                </div>
              ))}
            </div>
          </div>
  
          <div className="analysis-actions">
            <button
              onClick={processText}
              disabled={isAnalyzing || (isCustomSegmentation && hasEmptySegments())}
              className="primary-button"
            >
              {isAnalyzing ? 'Analyzing...' : 'Analyze Text'}
            </button>
            
            <button
              onClick={exportAnalysisCSV}
              disabled={!segments.length}
              className="secondary-button"
            >
              Export CSV
            </button>
          </div>
  
          {errorMessage && <div className="error-message">{errorMessage}</div>}
        </div>
  
        {segments.length > 0 && (
          <div className="visualization-section">
            <h2>Analysis Results</h2>
            
            <div className="chart-container">
              <h3>Emotional Arc</h3>
              <ResponsiveContainer width="100%" height={400}>
                {visualizationType === 'line' ? (
                  <LineChart data={formatEmotionalChangesData()}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" />
                    <YAxis domain={[0, 10]} />
                    <Tooltip />
                    <Legend />
                    {Object.keys(EMOTION_WEIGHTS).map(emotion => (
                      <Line
                        key={emotion}
                        type="monotone"
                        dataKey={emotion}
                        stroke={getEmotionColor(emotion)}
                      />
                    ))}
                  </LineChart>
                ) : visualizationType === 'area' ? (
                  <AreaChart data={formatEmotionalChangesData()}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" />
                    <YAxis domain={[0, 10]} />
                    <Tooltip />
                    <Legend />
                    {Object.keys(EMOTION_WEIGHTS).map(emotion => (
                      <Area
                        key={emotion}
                        type="monotone"
                        dataKey={emotion}
                        stroke={getEmotionColor(emotion)}
                        fill={getEmotionColor(emotion)}
                        stackId="1"
                      />
                    ))}
                  </AreaChart>
                ) : visualizationType === 'bar' ? (
                  <BarChart data={formatEmotionalChangesData()}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" />
                    <YAxis domain={[0, 10]} />
                    <Tooltip />
                    <Legend />
                    {Object.keys(EMOTION_WEIGHTS).map(emotion => (
                      <Bar
                        key={emotion}
                        dataKey={emotion}
                        fill={getEmotionColor(emotion)}
                      />
                    ))}
                  </BarChart>
                ) : (
                  <AreaChart data={formatEmotionalChangesData()}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" />
                    <YAxis domain={[0, 10]} />
                    <Tooltip />
                    <Legend />
                    {Object.keys(EMOTION_WEIGHTS).map(emotion => (
                      <Area
                        key={emotion}
                        type="monotone"
                        dataKey={emotion}
                        stroke={getEmotionColor(emotion)}
                        fill={getEmotionColor(emotion)}
                        stackId="1"
                      />
                    ))}
                  </AreaChart>
                )}
              </ResponsiveContainer>
            </div>
  
            <div className="secondary-charts">
              <div className="chart-card">
                <h3>Narrative Tension</h3>
                <ResponsiveContainer width="100%" height={300}>
                  <LineChart data={formatNarrativeTensionData()}>
                    <Line type="monotone" dataKey="value" stroke="#d62728" />
                    <XAxis dataKey="name" />
                    <YAxis domain={[0, 10]} />
                    <Tooltip />
                  </LineChart>
                </ResponsiveContainer>
              </div>
  
              <div className="chart-card">
                <h3>Action Pace</h3>
                <ResponsiveContainer width="100%" height={300}>
                  <BarChart data={formatActionPaceData()}>
                    <Bar dataKey="value" fill="#2ca02c" />
                    <XAxis dataKey="name" />
                    <YAxis domain={[0, 10]} />
                    <Tooltip />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
  
            {characterDangerAnalysisEnabled && (
              <div className="chart-container">
                <h3>Character-Danger Proximity</h3>
                <ResponsiveContainer width="100%" height={300}>
                  <AreaChart data={formatCharacterDangerData()}>
                    <Area
                      type="monotone"
                      dataKey="value"
                      stroke="#8c564b"
                      fill="#8c564b"
                    />
                    <XAxis dataKey="name" />
                    <YAxis domain={[0, 10]} />
                    <Tooltip />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default App;